INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_BURKERT_MYSTERY_CULTS','secondary scholarship','Walter Burkert, Ancient Mystery Cults (Harvard University Press, 1987)','The Greco-Roman mystery cults (Eleusinian, Samothracian/Cabiric, Dionysiac, Metroac, Mithraic): organization, initiation, theology, and inner casts.'),
 ('SRC_COLE_THEOI_MEGALOI','secondary scholarship','Susan Guettel Cole, Theoi Megaloi: The Cult of the Great Gods at Samothrace (EPRO 96, Brill, 1984)','The Samothracian Great Gods, their named tetrad (Axieros, Axiokersa, Axiokersos, Kadmilos), epigraphy, and Cabiric identifications.'),
 ('SRC_BURKERT_GREEK_RELIGION','secondary scholarship','Walter Burkert, Greek Religion: Archaic and Classical (Harvard University Press, 1985)','Reused existing source: Greek civic and mystery religion, Eleusinian cult personnel and the Eumolpid hierophants.')
INSERT INTO _e VALUES
 ('ENT_MYST_ELEUSINIAN','Eleusinian Mysteries (cult hub)','Initiate order','Initiate order','Greek','mystery initiation; Demeter-Kore cult; agrarian-eschatological soteriology','B','Hub collective for the inner cast of the Eleusinian Mysteries near Athens; abundantly attested epigraphically and in the Homeric Hymn to Demeter (Burkert, Ancient Mystery Cults; Greek Religion).'),
 ('ENT_MYST_SAMOTHRACIAN','Samothracian Mysteries (cult hub)','Initiate order','Initiate order','Greek','mystery initiation; Great Gods/Cabiric cult; protection at sea','B','Hub collective for the cult of the Great Gods (Theoi Megaloi) on Samothrace, paired with the existing Great Gods / Cabeiri entities (Cole, Theoi Megaloi; Burkert, Ancient Mystery Cults).'),
 ('ENT_MYST_BAUBO','Baubo','Eleusinian figure','Eleusinian figure','Greek','ribald jesting; consolation of Demeter; fertility/anasyrma','B','Old woman of Eleusis whose obscene jesting (the iambe/anasyrma motif) makes the grieving Demeter laugh; attested in Orphic fragments and Clement of Alexandria; terracotta Baubo figurines widespread (Burkert, Ancient Mystery Cults).'),
 ('ENT_MYST_EUMOLPUS','Eumolpus','Eleusinian hero','Eleusinian hero','Greek','founding hierophancy; Eleusinian priesthood (Eumolpidai)','B','Legendary founding hierophant of Eleusis and eponym of the Eumolpid priestly clan that supplied the hierophants; named in the Homeric Hymn to Demeter and Athenian tradition (Burkert, Greek Religion; Ancient Mystery Cults).'),
 ('ENT_MYST_DEMOPHOON','Demophoon','Eleusinian figure','Eleusinian figure','Greek','infant immortalization rite; nursing by Demeter','B','Infant son of Keleos and Metaneira whom the disguised Demeter nurses and attempts to immortalize in fire at Eleusis; central episode of the Homeric Hymn to Demeter (Burkert, Ancient Mystery Cults).'),
 ('ENT_MYST_DAEIRA','Daeira','Chthonic/mystery goddess','Chthonic/mystery goddess','Greek','Eleusinian chthonic divinity; the ''Knowing One''','C','Minor Eleusinian goddess (the ''Knowing One''), variously identified with Persephone or an Oceanid and given her own priestess and sacrifices at Eleusis; attested in Attic cult and lexicographers (Burkert, Greek Religion).'),
 ('ENT_MYST_AXIEROS','Axieros','Mystery cult deity','Mystery cult deity','Greek','Samothracian Great Goddess; great-mother/chthonic','B','Named member of the Samothracian tetrad, the Great Goddess identified by ancient sources with Demeter (and the Cybele-type Great Mother); attested in scholia to Apollonius and Samothracian epigraphy (Cole, Theoi Megaloi).'),
 ('ENT_MYST_AXIOKERSA','Axiokersa','Mystery cult deity','Mystery cult deity','Greek','Samothracian Great Goddess; underworld bride','B','Named member of the Samothracian tetrad, identified by the ancient scholia with Persephone; consort of Axiokersos (Cole, Theoi Megaloi; Burkert, Ancient Mystery Cults).'),
 ('ENT_MYST_AXIOKERSOS','Axiokersos','Mystery cult deity','Mystery cult deity','Greek','Samothracian Great God; underworld lord','B','Named member of the Samothracian tetrad, identified by ancient sources with Hades (and sometimes Ares); consort of Axiokersa (Cole, Theoi Megaloi).'),
 ('ENT_MYST_KADMILOS','Kadmilos (Kasmilos)','Mystery cult deity','Mystery cult deity','Greek','Samothracian servant-god; ithyphallic messenger; Cabiric attendant','B','Fourth member of the Samothracian tetrad, the youthful attendant-god identified by the scholia with Hermes; closely tied to the Cabeiri (Cole, Theoi Megaloi; Burkert, Ancient Mystery Cults).'),
 ('ENT_MYST_THEOS_HYPSISTOS','Theos Hypsistos (the Most High God)','Cult title/aspect','Cult title/aspect','Greek','pan-Mediterranean monotheizing high-god cult; Hypsistarian worship','C','The ''Most High God'' venerated across the Roman East by pagans, God-fearers, and the Hypsistarians; attested in hundreds of dedicatory inscriptions and patristic notices, partly converging with the Jewish God (Yahweh). A cult-title rather than a single named deity (Mitchell; Burkert, Ancient Mystery Cults).');
