INSERT INTO _p VALUES
 ('ENT_MYST_ELEUSINIAN','PER_GRK_ARCHAIC','Hub collective for the inner cast of the Eleusinian Mysteries near Athens; abundantly attested epigraphically and in the Homeric Hymn to Demeter (Burkert, Ancient Mystery Cults; Greek Religion).'),
 ('ENT_MYST_SAMOTHRACIAN','PER_GRK_ARCHAIC','Hub collective for the cult of the Great Gods (Theoi Megaloi) on Samothrace, paired with the existing Great Gods / Cabeiri entities (Cole, Theoi Megaloi; Burkert, Ancient Mystery Cults).'),
 ('ENT_MYST_BAUBO','PER_GRK_ARCHAIC','Old woman of Eleusis whose obscene jesting (the iambe/anasyrma motif) makes the grieving Demeter laugh; attested in Orphic fragments and Clement of Alexandria; terracotta Baubo figurines widespread (Burkert, Ancient Mystery Cults).'),
 ('ENT_MYST_EUMOLPUS','PER_GRK_ARCHAIC','Legendary founding hierophant of Eleusis and eponym of the Eumolpid priestly clan that supplied the hierophants; named in the Homeric Hymn to Demeter and Athenian tradition (Burkert, Greek Religion; Ancient Mystery Cults).'),
 ('ENT_MYST_DEMOPHOON','PER_GRK_ARCHAIC','Infant son of Keleos and Metaneira whom the disguised Demeter nurses and attempts to immortalize in fire at Eleusis; central episode of the Homeric Hymn to Demeter (Burkert, Ancient Mystery Cults).'),
 ('ENT_MYST_DAEIRA','PER_GRK_ARCHAIC','Minor Eleusinian goddess (the ''Knowing One''), variously identified with Persephone or an Oceanid and given her own priestess and sacrifices at Eleusis; attested in Attic cult and lexicographers (Burkert, Greek Religion).'),
 ('ENT_MYST_AXIEROS','PER_GRK_ARCHAIC','Named member of the Samothracian tetrad, the Great Goddess identified by ancient sources with Demeter (and the Cybele-type Great Mother); attested in scholia to Apollonius and Samothracian epigraphy (Cole, Theoi Megaloi).'),
 ('ENT_MYST_AXIOKERSA','PER_GRK_ARCHAIC','Named member of the Samothracian tetrad, identified by the ancient scholia with Persephone; consort of Axiokersos (Cole, Theoi Megaloi; Burkert, Ancient Mystery Cults).'),
 ('ENT_MYST_AXIOKERSOS','PER_GRK_ARCHAIC','Named member of the Samothracian tetrad, identified by ancient sources with Hades (and sometimes Ares); consort of Axiokersa (Cole, Theoi Megaloi).'),
 ('ENT_MYST_KADMILOS','PER_GRK_ARCHAIC','Fourth member of the Samothracian tetrad, the youthful attendant-god identified by the scholia with Hermes; closely tied to the Cabeiri (Cole, Theoi Megaloi; Burkert, Ancient Mystery Cults).'),
 ('ENT_MYST_THEOS_HYPSISTOS','PER_LATE_ANTIQUE','The ''Most High God'' venerated across the Roman East by pagans, God-fearers, and the Hypsistarians; attested in hundreds of dedicatory inscriptions and patristic notices, partly converging with the Jewish God (Yahweh). A cult-title rather than a single named deity (Mitchell; Burkert, Ancient Mystery Cults).');
