INSERT INTO _r VALUES
 ('ENT_MYST_BAUBO','member_of','ENT_MYST_ELEUSINIAN','high','Baubo is part of the Eleusinian cult cast (the iambe/jesting episode of the Homeric Hymn to Demeter).'),
 ('ENT_MYST_EUMOLPUS','member_of','ENT_MYST_ELEUSINIAN','high','Eumolpus is the legendary founding hierophant of the Eleusinian Mysteries and eponym of the Eumolpidai.'),
 ('ENT_MYST_DEMOPHOON','member_of','ENT_MYST_ELEUSINIAN','high','Demophoon''s immortalization episode is a foundational Eleusinian narrative.'),
 ('ENT_MYST_DAEIRA','member_of','ENT_MYST_ELEUSINIAN','medium','Daeira received her own priestess and sacrifices within the Eleusinian cult complex.'),
 ('ENT_DEMETER','presides_over','ENT_MYST_ELEUSINIAN','high','Demeter is the principal goddess of the Eleusinian Mysteries.'),
 ('ENT_PERSEPHONE','presides_over','ENT_MYST_ELEUSINIAN','high','Persephone (Kore) is the central abducted-and-returned goddess of the Eleusinian cult.'),
 ('ENT_MYST_DEMOPHOON','associated_with','ENT_DEMETER','high','Demeter nurses the infant Demophoon and attempts to immortalize him in the Homeric Hymn to Demeter.'),
 ('ENT_MYST_BAUBO','associated_with','ENT_DEMETER','high','Baubo''s obscene jesting consoles the grieving Demeter at Eleusis.'),
 ('ENT_MYST_DAEIRA','identified_with','ENT_PERSEPHONE','medium','Ancient sources variously identify the Eleusinian Daeira with Persephone.'),
 ('ENT_MYST_EUMOLPUS','associated_with','ENT_TRIPTOLEMUS','medium','Eumolpus and Triptolemus are paired Eleusinian founder-heroes in Athenian tradition.'),
 ('ENT_MYST_AXIEROS','member_of','ENT_MYST_SAMOTHRACIAN','high','Axieros is a named member of the Samothracian Great Gods tetrad.'),
 ('ENT_MYST_AXIOKERSA','member_of','ENT_MYST_SAMOTHRACIAN','high','Axiokersa is a named member of the Samothracian Great Gods tetrad.'),
 ('ENT_MYST_AXIOKERSOS','member_of','ENT_MYST_SAMOTHRACIAN','high','Axiokersos is a named member of the Samothracian Great Gods tetrad.'),
 ('ENT_MYST_KADMILOS','member_of','ENT_MYST_SAMOTHRACIAN','high','Kadmilos/Kasmilos is the fourth named member of the Samothracian Great Gods tetrad.'),
 ('ENT_MYST_AXIEROS','member_of','ENT_GREAT_GODS_SAMOTHRACE','high','The tetrad collectively constitutes the existing Great Gods of Samothrace.'),
 ('ENT_MYST_AXIOKERSA','member_of','ENT_GREAT_GODS_SAMOTHRACE','high','Axiokersa is one of the existing Great Gods of Samothrace.'),
 ('ENT_MYST_AXIOKERSOS','member_of','ENT_GREAT_GODS_SAMOTHRACE','high','Axiokersos is one of the existing Great Gods of Samothrace.'),
 ('ENT_MYST_KADMILOS','member_of','ENT_GREAT_GODS_SAMOTHRACE','high','Kadmilos is one of the existing Great Gods of Samothrace.'),
 ('ENT_MYST_KADMILOS','associated_with','ENT_CABEIRI','high','Kadmilos is closely linked to the Cabeiri as their attendant/father-figure in the Samothracian-Cabiric tradition.'),
 ('ENT_MYST_AXIEROS','equated_with','ENT_DEMETER','medium','Ancient interpretatio (scholia to Apollonius) identifies the Samothracian Axieros with Demeter.'),
 ('ENT_MYST_AXIEROS','equated_with','ENT_CYBELE','medium','Axieros as the Samothracian Great Mother was also identified with the Cybele-type Mother of the Gods.'),
 ('ENT_MYST_AXIOKERSA','equated_with','ENT_PERSEPHONE','medium','Ancient scholia identify the Samothracian Axiokersa with Persephone.'),
 ('ENT_MYST_AXIOKERSOS','equated_with','ENT_HADES','medium','Ancient scholia identify the Samothracian Axiokersos with Hades.'),
 ('ENT_MYST_KADMILOS','equated_with','ENT_HERMES','medium','Ancient scholia identify the Samothracian Kadmilos/Kasmilos with Hermes.'),
 ('ENT_MYST_THEOS_HYPSISTOS','syncretized_with','ENT_ZEUS','medium','The ''Most High God'' cult-title often attached to Zeus (Zeus Hypsistos) in pagan dedications across the Roman East.'),
 ('ENT_MYST_THEOS_HYPSISTOS','aligned_with','ENT_ISR_YAHWEH','medium','The Theos Hypsistos / Hypsistarian cult partly converged with the worship of the Jewish God among God-fearers, blurring pagan and Jewish monotheizing devotion.');
